    text(`全队获得 ${r.xp} 经验`, 640, 358, 15, '#d8c8a8', 'center', 400);
    if (r.ups && r.ups.length) text(r.ups.slice(0, 2).join(' · '), 640, 384, 13, '#8fd9c0', 'center', 500, true);
