input.old_string:
forceCapture: () => {
  if (!battle || battle.bossIdx >= 0) return false;
  const foe = enemyActive(); if (!foe) return false;
  foe.hp = 1; battle.phase = 'menu';
  const old = rngState;
  // guarantee the next roll: compute chance then bias the RNG state is awkward;
  // instead run the true capture path with hp 1 and retry a few seeded rolls.
  for (let k = 0; k < 12; k++) {
    if (battle.phase !== 'menu') break;
    throwSeal();
    if (battle && battle.capturePending) { upd(90); return true; }
    if (battle && battle.phase === 'resolving') upd(200);
    if (battle && battle.phase === 'menu') foe.hp = 1;
  }
  rngState = old;
  return false;
},

input.new_string:
forceCapture: () => {
  if (!battle || battle.bossIdx >= 0) return false;
  const foe = enemyActive(); if (!foe) return false;
  foe.hp = Math.max(1, Math.min(foe.maxHp, 1));
  battle.phase = 'menu';
  battle.forceCatch = true;
  throwSeal();
  upd(90);
  return !!(battle && battle.result && battle.result.kind === 'capture');
},

