// T9 seal consumption & reject
{
  G.startWild('tideotter', 5);
  G.setSeals(0);
  const no = G.throwSeal();
  const after0 = G.state().seals;
  G.setSeals(2);
  G.setEnemyHp(9999);
  const yes = G.throwSeal();
